local item_lib = require("items")
local function staging(e)
 return e.qglobals.coldainWarPhase=="staging" and e.qglobals.coldainWarStaging=="active"
end

local nextconv=0
local briefing={"We knew the day might come when the Kromrif would discover the location of our beloved city. It was only prudent for there to be a plan for such a circumstance. In light of recent developments, however, our plans have been adjusted. Outlander, the Dain has appointed you to lead our armies in defense of Thurgadin.",
"I will stand here with a handful of men as a final line of defense. Should I fall, all will be lost. You will have these men and their soldiers to command. Use them wisely, you will be richly rewarded if your forces are able to keep them alive.",
"Garadain will post his men in the gorge to the east. Churn and his men will await your command in the caves to the west. Dobbin will have his forces at the ready in the clearing directly south of here near the towers. If any Kromrif make it to his vicinity he and his men will attack with or without your command.",
"Lastly, Corbin will hide his men in the worm caves to the south, call on him for a surprise attack. Remember where these men are stationed, outlander. Should they call out for help you may wish to send some of your people to aid them.",
"The leader of this invasion is a powerful Kromrif named Narandi. Rumor has it that he is more powerful than any ten of his peers. He must fall. When he is slain you must show his head and the ninth ring to me.",
"Scout Zrelik here will follow you and serve as your herald. He will relay your orders to the troops. Show me your ninth ring now to verify your identity and I will give you the orders to memorize."}
function event_signal(e)
 if e.self:GetNPCTypeID()==2000965 and e.signal==1 and staging(e) then
  eq.set_timer("conversation",14000)
 end
end
function event_timer(e)
 if not staging(e) then eq.stop_all_timers();return end
 if e.timer=="conversation" then
  eq.stop_timer(e.timer);nextconv=1
  e.self:Say(briefing[nextconv]);eq.set_timer("continue",7000)
 elseif e.timer=="continue" then
  nextconv=nextconv+1
  e.self:Say(briefing[nextconv])
  if nextconv==#briefing then eq.stop_timer(e.timer) end
 end
end
function event_trade(e)
 if e.self:GetNPCTypeID()==2000965 and staging(e) and item_lib.check_turn_in(e.trade,{item1=30369}) then
  e.other:SummonItem(30369)
  if not e.other:HasItem(18511) then
   e.other:SummonItem(18511)
   e.self:Say("Commit these orders to memory. When the orders are handed to Zrelik we will take up our positions.")
  end
  eq.stop_all_timers()
 end
 item_lib.return_items(e.self,e.other,e.trade)
end
